TSharedRef<SWidget> UNarrativeStoryWidget::RebuildWidget()
{
    if (WidgetTree && !WidgetTree->RootWidget)
    {
        Root = WidgetTree->ConstructWidget<UCanvasPanel>(UCanvasPanel::StaticClass(), TEXT("Root"));
        WidgetTree->RootWidget = Root;
        LoadTheme();
        Layout();
    }
    return Super::RebuildWidget();
}

void UNarrativeStoryWidget::NativeConstruct()
{
    Super::NativeConstruct();
    SetIsFocusable(true);
    SettingsHandle = UNarrativeSettings::OnChanged().AddUObject(this, &UNarrativeStoryWidget::Rebuild);
    LanguageHandle = UNarrativeLocalization::OnChanged().AddUObject(this, &UNarrativeStoryWidget::Rebuild);
}

void UNarrativeStoryWidget::NativeDestruct()
{
    UNarrativeSettings::OnChanged().Remove(SettingsHandle);
    UNarrativeLocalization::OnChanged().Remove(LanguageHandle);
    Bind(false);
    Super::NativeDestruct();
}

void UNarrativeStoryWidget::SetStory(UNarrativeBridgeComponent* InStory)
{
    Bind(false);
    Story = InStory;
    Bind(true);
    if (Story) Story->VoiceVolume = Theme.VoiceVolume;
    Redraw();
}

void UNarrativeStoryWidget::Bind(bool bOn)
{
    if (!Story) return;
    if (bOn)
    {
        Story->OnLineShown.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleLine);
        Story->OnChoices.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleChoices);
        Story->OnContinue.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleContinue);
        Story->OnEnded.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleEnded);
        Story->OnExit.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleExit);
        Story->OnResumed.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleResumed);
        Story->OnRestarted.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleRestarted);
        Story->OnStatusChanged.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleStatus);
    }
    else
    {
        Story->OnLineShown.RemoveAll(this);
        Story->OnChoices.RemoveAll(this);
        Story->OnContinue.RemoveAll(this);
        Story->OnEnded.RemoveAll(this);
        Story->OnExit.RemoveAll(this);
        Story->OnResumed.RemoveAll(this);
        Story->OnRestarted.RemoveAll(this);
        Story->OnStatusChanged.RemoveAll(this);
    }
}

void UNarrativeStoryWidget::LoadTheme()
{
    if (ThemeAsset) Theme = ThemeAsset->Theme;
    else UNarrativeThemeLibrary::LoadStoryTheme(Theme);
    if (UNarrativeSettings::GetHighContrast())
    {
        // Light text on a solid dark panel, whatever the theme's colours.
        Theme.Background = FLinearColor(0.f, 0.f, 0.f, 1.f);
        Theme.PanelOpacity = 1.f;
        Theme.Text = Theme.ChoiceTextColour = FLinearColor::White;
        Theme.SpeakerColour = Theme.Accent = Theme.BorderColour = FLinearColor(1.f, 0.65f, 0.12f, 1.f);
        Theme.SceneColour = Theme.Muted = FLinearColor(0.8f, 0.8f, 0.8f, 1.f);
        Theme.ButtonColour = FLinearColor(1.f, 1.f, 1.f, 1.f);
        Theme.ButtonOpacity = FMath::Max(Theme.ButtonOpacity, 0.25f);
    }
}

void UNarrativeStoryWidget::Rebuild()
{
    if (!Root) return;
    LoadTheme();
    Layout();
    Redraw();
}

